#include <stdio.h>
#include <stdlib.h>

#define MAX_ITEMS 5

typedef struct {
    int sku;
    int quantity;
    int price;
} item;

item inventory[MAX_ITEMS];

void restock(int sku, int quantity) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        if (inventory[i].sku == sku) {
            inventory[i].quantity += quantity;
            printf("RESTOCK sku=%d qty=%d\n", sku, quantity);
            return;
        }
    }
    printf("INVALID_SKU\n");
}

void sell(int sku, int quantity) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        if (inventory[i].sku == sku) {
            if (inventory[i].quantity >= quantity) {
                inventory[i].quantity -= quantity;
                int revenue = quantity * inventory[i].price;
                printf("SELL sku=%d qty=%d revenue+=%d\n", sku, quantity, revenue);
            } else {
                printf("INSUFFICIENT_STOCK sku=%d\n", sku);
            }
            return;
        }
    }
    printf("INVALID_SKU\n");
}

void print_inventory() {
    printf("FINAL stock=");
    for (int i = 0; i < MAX_ITEMS; i++) {
        printf("%d", inventory[i].quantity);
        if (i < MAX_ITEMS - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    for (int i = 0; i < MAX_ITEMS; i++) {
        inventory[i].sku = i + 1;
        inventory[i].quantity = 0;
        inventory[i].price = 10;
    }

    for (int i = 1; i < argc; i += 3) {
        char *op = argv[i];
        int sku = atoi(argv[i + 1]);
        int quantity = atoi(argv[i + 2]);

        if (strcmp(op, "S") == 0) {
            sell(sku, quantity);
        } else if (strcmp(op, "R") == 0) {
            restock(sku, quantity);
        } else {
            printf("INVALID_OP\n");
        }
    }

    print_inventory();

    return 0;
}
